const userEventsBetween = `-- name: UserEventsBetween :many
SELECT e.install_id, e.seq, e.ts, e.kind, e.session_id, e.project_id, e.harness, e.source, e.data, e.received_at, e.prev_hash, e.hash FROM events e
JOIN installs i ON i.id = e.install_id
WHERE i.user_id = $1 AND e.ts >= $2 AND e.ts < $3
ORDER BY e.ts, e.seq
`

type UserEventsBetweenParams struct {
	UserID string
	FromTs pgtype.Timestamptz
	ToTs   pgtype.Timestamptz
}

func (q *Queries) UserEventsBetween(ctx context.Context, arg UserEventsBetweenParams) ([]Event, error) {
	rows, err := q.db.Query(ctx, userEventsBetween, arg.UserID, arg.FromTs, arg.ToTs)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []Event
	for rows.Next() {
		var i Event
		if err := rows.Scan(
			&i.InstallID,
			&i.Seq,
			&i.Ts,
			&i.Kind,
			&i.SessionID,
			&i.ProjectID,
			&i.Harness,
			&i.Source,
			&i.Data,
			&i.ReceivedAt,
			&i.PrevHash,
			&i.Hash,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

